using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata retrieval
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> – kind: {typedInfo.Kind}, type: {typedInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), typedInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Deserialized: {p}");

// 2. Probe without throwing – TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded – kind: {info!.Kind}");
}

// Probe for a type that has NO resolver (use empty chain → nothing resolves)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty – resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Unexpected: resolved Person on limited options");
else
    Console.WriteLine("\nTryGetTypeInfo(Person) on limited options returned false – no exception thrown.");

record Person(string Name, int Age);

